import{_ as t,o as e,c as i,ag as l}from"./chunks/framework.DWOJQht4.js";const u=JSON.parse('{"title":"技术架构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1792724420000}'),s={name:"guide/architecture.md"};function d(r,a,o,n,h,c){return e(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h1><p>CloudCTF 当前采用 <strong>Go 后端 + 内嵌前端 + 单二进制交付</strong> 的架构方案，生产环境主推 <code>systemd</code> 直接托管服务进程。</p><h2 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  User[&quot;浏览器用户&quot;] --&gt; Server[&quot;CloudCTF Server&lt;br/&gt;单二进制&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Admin[&quot;管理员&quot;] --&gt; Server</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Server --&gt; DB[&quot;业务数据库&lt;br/&gt;SQLite / MySQL / PostgreSQL&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Server --&gt; Files[&quot;本地文件存储&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Server --&gt; Docker[&quot;Docker / 容器运行时&quot;]</span></span></code></pre></div><p>说明：</p><ul><li><strong>前端已内嵌</strong>：选手端与管理后台静态资源都由 <code>CloudCTF Server</code> 直接提供</li><li><strong>数据库可配置</strong>：默认 SQLite，生产可切换 MySQL 或 PostgreSQL</li><li><strong>动态靶机运行时独立</strong>：平台本身不依赖 Docker 部署，但动态题目运行仍可依赖 Docker</li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><h3 id="_1-cloudctf-server" tabindex="-1">1. CloudCTF Server <a class="header-anchor" href="#_1-cloudctf-server" aria-label="Permalink to &quot;1. CloudCTF Server&quot;">​</a></h3><p>主职责：</p><ul><li>提供 <code>/</code> 与 <code>/admin</code> 页面</li><li>提供 <code>/api</code>、<code>/api-admin</code>、<code>/api/public</code> 接口</li><li>处理认证、比赛、题目、理论考试、公告、审计、备份等核心业务</li></ul><p>特点：</p><ul><li>单二进制交付</li><li>内嵌前端资源</li><li>可直接由 <code>systemd</code> 托管</li></ul><h3 id="_2-数据库" tabindex="-1">2. 数据库 <a class="header-anchor" href="#_2-数据库" aria-label="Permalink to &quot;2. 数据库&quot;">​</a></h3><p>当前通过 <code>DATABASE_URI</code> 配置。</p><p>支持场景：</p><ul><li><strong>SQLite</strong>：单机、零依赖、快速启动</li><li><strong>MySQL</strong>：生产环境推荐</li><li><strong>PostgreSQL</strong>：使用 PostgreSQL 基础设施的生产环境</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>Go</td><td>主服务语言</td></tr><tr><td>net/http</td><td>HTTP 服务</td></tr><tr><td>GORM</td><td>ORM 与数据库访问</td></tr><tr><td>SQLite / MySQL / PostgreSQL Driver</td><td>可切换数据库</td></tr></tbody></table><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>React</td><td>UI 框架</td></tr><tr><td>TypeScript</td><td>类型系统</td></tr><tr><td>Vite</td><td>构建工具</td></tr><tr><td>Ant Design</td><td>管理后台组件</td></tr></tbody></table><h3 id="运行时与交付" tabindex="-1">运行时与交付 <a class="header-anchor" href="#运行时与交付" aria-label="Permalink to &quot;运行时与交付&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>systemd</td><td>生产环境服务托管</td></tr><tr><td>单二进制</td><td>主服务交付形式</td></tr><tr><td>Docker</td><td>动态靶机与漏洞环境运行时</td></tr></tbody></table><h2 id="路由结构" tabindex="-1">路由结构 <a class="header-anchor" href="#路由结构" aria-label="Permalink to &quot;路由结构&quot;">​</a></h2><p>当前前后端契约如下：</p><ul><li><code>GET /</code>：选手端页面</li><li><code>GET /admin</code>：管理后台页面</li><li><code>/api</code>：选手端 API</li><li><code>/api-admin</code>：管理端 API</li><li><code>/api/public</code>：公共 API</li></ul><p>这意味着：</p><ol><li>不需要单独部署前端站点</li><li>不需要额外配置前端反向代理才能访问管理端</li><li>升级时只需要替换服务二进制</li></ol><h2 id="生产部署架构" tabindex="-1">生产部署架构 <a class="header-anchor" href="#生产部署架构" aria-label="Permalink to &quot;生产部署架构&quot;">​</a></h2><h3 id="推荐单机生产架构" tabindex="-1">推荐单机生产架构 <a class="header-anchor" href="#推荐单机生产架构" aria-label="Permalink to &quot;推荐单机生产架构&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Client[&quot;浏览器访问&quot;] --&gt; Server[&quot;cloudctf.service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Server --&gt; DB[&quot;SQLite / MySQL / PostgreSQL&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Server --&gt; Files[&quot;/opt/cloudctf/data&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Server --&gt; Docker[&quot;Docker Engine&quot;]</span></span></code></pre></div><p>适用场景：</p><ul><li>企业内部竞赛平台</li><li>培训平台</li><li>理论考试平台</li><li>中小规模单机部署</li></ul><h2 id="文件与数据" tabindex="-1">文件与数据 <a class="header-anchor" href="#文件与数据" aria-label="Permalink to &quot;文件与数据&quot;">​</a></h2><p>生产环境中通常需要持久化这些目录：</p><ul><li><code>data/</code></li><li><code>uploads/</code></li><li><code>backups/</code></li><li><code>logs/</code></li></ul><p>典型部署目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opt/cloudctf/</span></span>
<span class="line"><span>  bin/</span></span>
<span class="line"><span>  config/</span></span>
<span class="line"><span>  data/</span></span>
<span class="line"><span>  logs/</span></span></code></pre></div><h2 id="为什么要改成单二进制方案" tabindex="-1">为什么要改成单二进制方案 <a class="header-anchor" href="#为什么要改成单二进制方案" aria-label="Permalink to &quot;为什么要改成单二进制方案&quot;">​</a></h2><p>相较旧的容器化主服务部署方式，当前方案有这些优势：</p><ul><li>部署链路更短</li><li>前后端版本天然一致</li><li>升级动作更简单</li><li>更容易接入已有 Linux 服务器与运维体系</li><li>对于不需要完整容器编排的平台场景更轻量</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/CloudCTF/guide/quick-start.html">快速开始</a></li><li><a href="/CloudCTF/guide/admin-guide.html">管理员指南</a></li><li><a href="/CloudCTF/guide/faq.html">常见问题</a></li></ul>`,43)])])}const g=t(s,[["render",d]]);export{u as __pageData,g as default};
